<script setup>
import machinesData from '~/assets/data/machines.json'
import p1 from '~/assets/data/haasHistoricalModels1.json'
import p2 from '~/assets/data/haasHistoricalModels2.json'
import p3 from '~/assets/data/haasHistoricalModels3.json'
import p4 from '~/assets/data/haasHistoricalModels4.json'
const query=ref('')
const all=[...p1,...p2,...p3,...p4]
const usableCount=m=>m.records.filter(r=>r.summary?.trim()).length
const models=computed(()=>all.filter(m=>usableCount(m)>0).sort((a,b)=>a.model.localeCompare(b.model)))
const recordCount=computed(()=>all.reduce((n,m)=>n+m.records.length,0))
const filtered=computed(()=>{const q=query.value.trim().toLowerCase();return q?models.value.filter(m=>m.model.toLowerCase().includes(q)):models.value})
const familyModels=prefix=>models.value.filter(m=>m.model.toUpperCase().startsWith(`${prefix}-`)||m.model.toUpperCase().startsWith(`${prefix} `)).slice(0,12)
const otherFamilyModels=computed(()=>models.value.filter(m=>/^(HL|DS|CL)[- ]/i.test(m.model)).slice(0,14))
const webDescription=m=>m.WebDesc||m.Web_Desc||m.AdvSpec||m.Adv_Spec||''
const offMarket=m=>m.OffMarket??m.Off_Market??0
const current=computed(()=>(machinesData||[]).filter(m=>Number(m.Sold)===0&&Number(offMarket(m))===0&&Number(m.dont_advertise||0)===0&&String(m.Groups||'').includes('CNC Lathes')&&String(m.Manufacturer||'').trim().toLowerCase()==='haas').sort((a,b)=>Number(b.Year||0)-Number(a.Year||0)))
const machineUrl=m=>`/equipment/${m.InvID}/${`${m.Manufacturer||''}-${m.Model||''}`.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}`
useSeoMeta({title:'Used Haas CNC Lathes | Specifications & Machines for Sale | UMS',description:'Browse Haas CNC lathe specifications by exact model and see current used Haas turning centers for sale from Used Machinery Source.'})
useHead({link:[{rel:'canonical',href:'https://usedmachinerysource.com/spec-library/haas/cnc-lathes'}]})
</script>
